import base64
import lzma
import subprocess
import sys

PATCH = ""
raw = lzma.decompress(base64.b64decode(PATCH))
result = subprocess.run(
    ["patch", "-p0", "--batch", "--forward"],
    cwd=sys.argv[1], input=raw, stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT, check=False,
)
print(result.stdout.decode("utf-8", errors="replace"))
if result.returncode != 0:
    raise SystemExit(result.returncode)
print("Applied Boletim Informativo 2.3.0 patch.")

from pathlib import Path
root = Path(sys.argv[1])
replacements = {
    "server.js": [
        ("Boletim Informativo 2.1.1 disponível na porta", "Boletim Informativo 2.3.0 disponível na porta"),
    ],
    "public/index.html": [
        ("<title>Boletim Informativo 2.1.1</title>", "<title>Boletim Informativo 2.3.0</title>"),
    ],
    "README.md": [
        ("# Boletim Informativo 2.2\n", "# Boletim Informativo 2.3.0\n"),
    ],
    "LEIA-ME.txt": [
        ("BOLETIM INFORMATIVO 2.2\n", "BOLETIM INFORMATIVO 2.3.0\n"),
        ("2.2.0 — envio de PDF por comunicado e hierarquia de Administrador Principal\ne Administradores Secundários, mantendo as funções da versão 2.1.1.", "2.3.0 — PDF por comunicado, hierarquia administrativa, confirmação de leitura,\nhistórico de edições e filtros avançados do mural."),
    ],
}
for rel, pairs in replacements.items():
    path = root / rel
    content = path.read_text()
    for old, new in pairs:
        if old not in content:
            raise SystemExit(f"Expected label not found in {rel}: {old!r}")
        content = content.replace(old, new, 1)
    path.write_text(content)
print("Polished version labels to 2.3.0.")
